// T-335 one reader: every list the app polls from the vault is read here, one reader per kind, on one poller.
//
// - The kinds and their fields come from the vault's tag schemas (schema.gen.ts, generated by scripts/vault-schema.py): a reader returns
//   notes whose metadata is typed by its kind.
// - One poller (`onPoll`): one timer for the whole app, a minute apart while the window is visible, and a tick when the window comes back
//   (focus, visible) after FOCUS_GAP_MS. Every screen part that keeps a list fresh subscribes to it instead of running its own timer.
// - Each read is shared within a tick: the same kind and query asked twice in one tick (the tasks and the work both want the nodes) is one
//   vault call. A write, a Retry or a manual refresh calls `invalidate()`: the next read goes to the vault.
// The parsing stays with the screens' pure cores (taskCore, forYouCore, projects/live); this module only reads.
import { invoke } from "@tauri-apps/api/core";
import type { Meta } from "./schema.gen.ts";

export type Kind = keyof Meta;
/** A note as a list read returns it (metadata only unless asked), its metadata typed by its kind. */
export type Note<K extends Kind = Kind> = {
  id?: unknown; path?: unknown; tags?: unknown; updatedAt?: unknown; createdAt?: unknown; lastUpdatedBy?: unknown; lastUpdatedVia?: unknown; content?: unknown;
  metadata?: (Meta[K] & Record<string, unknown>) | unknown;
};
export type Rows<K extends Kind = Kind> = { rows: Note<K>[]; complete: boolean };
export type Call = (cmd: string, args: Record<string, unknown>) => Promise<unknown>;

export const LIMIT = 200;
/** A list longer than this many pages (2000 notes) is read no further and said to be incomplete. */
const MAX_PAGES = 10;
/** The task states a live list asks for. */
export const LIVE = ["open", "doing", "waiting"] as const;
/** How often the poller ticks, and how long after the last tick coming back to the window ticks again. */
export const POLL_MS = 60_000;
export const FOCUS_GAP_MS = 10_000;
/** A read is shared with the rest of its tick, never longer than this (a tick's readers start within a render or two of each other). */
const SHARE_MS = 20_000;
/** A run in one of these states is still live (steerCore's isActiveRun: anything not done or failed): read whenever it started. */
export const LIVE_RUNS = ["running", "queued", "stalled", "blocked", "decision", "lost"] as const;
/** The runs a work read covers: every live run, and those started in these day windows (newest first). */
export const RUN_WINDOWS: readonly [number, number][] = [[0, 2], [2, 7], [7, 21], [21, 60]];
/** The run windows older than the first are read at most this often (see `runs`). */
export const OLD_RUNS_MS = 5 * 60_000;
const DAY = 86_400_000;

/**
 * Read a list page by page (200 at a time) until a short page. `complete` only when that last page came back short: a list that stops at
 * MAX_PAGES, or a vault that ignores `offset` (a page with nothing new), is incomplete, never taken for the whole.
 */
export async function allPages<N = Note>(page: (offset: number) => Promise<N[]>): Promise<{ rows: N[]; complete: boolean }> {
  const rows: N[] = []; const seen = new Set<string>();
  for (let i = 0; i < MAX_PAGES; i++) {
    const got = await page(i * LIMIT);
    let fresh = 0;
    for (const r of Array.isArray(got) ? got : []) {
      const id = typeof (r as { id?: unknown }).id === "string" ? (r as { id: string }).id : null;
      if (id && seen.has(id)) continue;
      if (id) seen.add(id);
      rows.push(r); fresh++;
    }
    if (!Array.isArray(got) || got.length < LIMIT) return { rows, complete: true };
    if (!fresh) return { rows, complete: false };
  }
  return { rows, complete: false };
}

/** The reader over one vault door (`call`): the app's is `reader`, a test makes its own with a fake door and clock. */
export function createReader(call: Call = (cmd, args) => invoke(cmd, args), clock: () => number = () => Date.now(),
  opts: { share?: boolean; /** a test's timer, with setInterval's meaning (it fires every `ms` until stopped) */ every?: (f: () => void, ms: number) => unknown; stopEvery?: (h: unknown) => void } = {}) {
  const sharing = opts.share !== false;
  // ---- sharing within a tick ----
  let generation = 0;
  const shared = new Map<string, { gen: number; at: number; p: Promise<unknown> }>();
  /** The next read goes to the vault (after a write, a Retry, a manual refresh, another vault or identity): of everything, or of these
   *  kinds only (`run`, `node`, `task-all`…: what a work view's follow-up read wants fresh, leaving the rest of the tick shared). */
  function invalidate(...kinds: string[]) {
    if (!kinds.length) { generation++; shared.clear(); return; }
    for (const k of [...shared.keys()]) if (kinds.includes(JSON.parse(k)[0])) shared.delete(k);
  }
  function share<T>(key: string, read: () => Promise<T>): Promise<T> {
    const now = clock();
    const had = shared.get(key);
    if (sharing && had && had.gen === generation && now - had.at < SHARE_MS) return had.p as Promise<T>;
    const p = read();
    const entry = { gen: generation, at: now, p };
    shared.set(key, entry);
    // a failed read is never shared: the next asker tries again
    p.catch(() => { if (shared.get(key) === entry) shared.delete(key); });
    return p;
  }

  const query = <K extends Kind>(vault: string, tag: K | string, content = false) => (offset: number) =>
    call("vault_query", { vault, tag, includeContent: content, limit: LIMIT, ...(offset ? { offset } : {}) }) as Promise<Note<K>[]>;
  const where = <K extends Kind>(vault: string, tag: K, metadata: Record<string, unknown>) => (offset: number) =>
    call("vault_query_meta", { vault, tag, metadata, limit: LIMIT, ...(offset ? { offset } : {}) }) as Promise<Note<K>[]>;
  const keyOf = (...parts: unknown[]) => JSON.stringify(parts);

  // ---- one reader per kind ----
  /** Every `node` note (the tree: the root, areas, projects), metadata only. */
  const nodes = (vault: string): Promise<Rows<"node">> => share(keyOf("node", vault), () => allPages(query<"node">(vault, "node")));
  /** The live tasks (open, doing, waiting), optionally under some nodes (`node in [...]`). */
  const liveTasks = (vault: string, nodeIn: readonly string[] | null = null): Promise<Rows<"task">> =>
    share(keyOf("task", vault, nodeIn), () => allPages(where(vault, "task", { ...(nodeIn ? { node: { in: [...nodeIn] } } : {}), state: { in: [...LIVE] } })));
  /** The open decisions (the older `Decisions/` notes, and a new decision while it is open), optionally under some nodes. */
  const openDecisions = (vault: string, nodeIn: readonly string[] | null = null): Promise<Rows<"decision">> =>
    share(keyOf("decision", vault, nodeIn), () => allPages(where(vault, "decision", { ...(nodeIn ? { node: { in: [...nodeIn] } } : {}), state: { in: ["open"] } })));
  /** Every task, any state (the work view places sessions under projects by their task). */
  const allTasks = (vault: string): Promise<Rows<"task">> => share(keyOf("task-all", vault), () => allPages(query<"task">(vault, "task")));
  /** The tasks closed (done or archived), for "closed since the summary was written". */
  const closedTasks = (vault: string): Promise<Rows<"task">> => share(keyOf("task-closed", vault), () => allPages(where(vault, "task", { state: { in: ["done", "archived"] } })));
  /** Every living card, metadata only. */
  const cards = (vault: string): Promise<Rows<"card">> => share(keyOf("card", vault), () => allPages(query<"card">(vault, "card")));
  /** Every draft note, metadata only. */
  const drafts = (vault: string): Promise<Rows<"draft">> => share(keyOf("draft", vault), () => allPages(query<"draft">(vault, "draft")));
  /**
   * The runs that matter now: every one still live (running, queued, stalled, blocked, waiting on a decision, lost: whenever it started), and those started in the last 60 days, a window at a time (newest first).
   * `partial` says which part a short read left out. Runs older than two days have mostly ended and change rarely: their windows are read at
   * most every OLD_RUNS_MS, and the fresh window reaches back to where that older read began, so no run falls between the two.
   */
  const old = new Map<string, { at: number; p: Promise<Rows<"run">[]> }>();
  /** The runs that already forced a re-read of the older windows, by vault (see `runs`). */
  const forcedFor = new Map<string, Set<unknown>>();
  const runs = (vault: string): Promise<{ rows: Note<"run">[]; partial: string[] }> => share(keyOf("run", vault), async () => {
    const now = clock();
    const iso = (at: number, days: number) => new Date(at - days * DAY).toISOString();
    const readOld = (at: number) => {
      const p = Promise.all(RUN_WINDOWS.slice(1).map(([to, from]) => allPages(where(vault, "run", { started_at: { gte: iso(at, from), lt: iso(at, to) } }))));
      const entry = { at, p };
      // a failed read is never kept: the next asks again
      p.catch(() => { if (old.get(vault) === entry) old.delete(vault); });
      old.set(vault, entry);
      return entry;
    };
    let o = old.get(vault);
    // (a clock that went back reads the older windows again too)
    if (!o || now - o.at >= OLD_RUNS_MS || now < o.at) o = readOld(now);
    const [running, recent, first] = await Promise.all([
      allPages(where(vault, "run", { state: { in: [...LIVE_RUNS] } })),
      allPages(where(vault, "run", { started_at: { gte: iso(o.at, RUN_WINDOWS[0][1]) } })),
      o.p,
    ]);
    let windows = first;
    // a run the older read saw live that the live read no longer lists has ended since (a stop, a finish): the older windows are read again
    // at once, so it is never shown live from a five-minute-old copy. Each such run forces one re-read only (a note the live query never
    // lists can't make every read a re-read); a re-read that fails keeps the windows already read. (The fresh window already reaches back
    // to where the older read began.)
    const liveNow = new Set(running.rows.map((r) => r.id));
    const forced = forcedFor.get(vault) ?? new Set<unknown>();
    const endedIds = running.complete ? windows.flatMap((w) => w.rows).filter((r) => LIVE_RUNS.includes((r.metadata as { state?: never } | undefined)?.state ?? ("" as never)) && !liveNow.has(r.id) && !forced.has(r.id)).map((r) => r.id) : [];
    if (endedIds.length && o.at !== now) {
      for (const id of endedIds) forced.add(id);
      forcedFor.set(vault, forced);
      // (a failed one evicts itself in readOld; its runs may force again on the next read)
      try { o = readOld(now); windows = await o.p; } catch { for (const id of endedIds) forced.delete(id); }
    }
    const seen = new Set<unknown>();
    const rows = [running, recent, ...windows].flatMap((r) => r.rows).filter((r) => (seen.has(r.id) ? false : (seen.add(r.id), true)));
    const partial = !running.complete || !recent.complete ? ["Some sessions aren't loaded"] : windows.some((w) => !w.complete) ? ["Some older sessions aren't loaded"] : [];
    return { rows, partial };
  });
  /** Forget (the user's Forget, another identity): nothing read before is shared or kept. */
  function forget() { invalidate(); old.clear(); forcedFor.clear(); }

  // ---- one poller ----
  const subs = new Set<() => void>();
  let timer: unknown = null;
  let lastTick: number | null = null;
  const visible = () => typeof document === "undefined" || document.visibilityState === "visible";
  const every = opts.every ?? ((f: () => void, ms: number) => setInterval(f, ms));
  const stopEvery = opts.stopEvery ?? ((h: unknown) => clearInterval(h as ReturnType<typeof setInterval>));
  const arm = () => { if (timer !== null) stopEvery(timer); timer = every(() => { if (visible()) tick(); }, POLL_MS); };
  /** Every subscriber reads again now (their reads shared within this tick). The timer starts over, so the next tick is a minute after
   *  this one, whatever brought it (the timer, or coming back to the window). */
  function tick() {
    lastTick = clock();
    if (timer !== null) arm();
    invalidate();
    for (const f of [...subs]) { try { f(); } catch { /* one screen part's failure is its own */ } }
  }
  // (a clock that went back, a device's time changed, reads as stale too: never "ticked a moment ago" for good)
  const onBack = () => { const now = clock(); if (visible() && (lastTick === null || now - lastTick >= FOCUS_GAP_MS || now < lastTick)) tick(); };
  /**
   * Keep something fresh: `f` runs on every tick (a minute apart while the window is visible, and on coming back to it). The first
   * subscriber starts the one timer, the last one stops it. Returns the unsubscribe.
   */
  function onPoll(f: () => void): () => void {
    subs.add(f);
    if (subs.size === 1 && typeof window !== "undefined") {
      lastTick = clock();
      arm();
      window.addEventListener("focus", onBack);
      document.addEventListener("visibilitychange", onBack);
    }
    return () => {
      if (!subs.delete(f) || subs.size) return;
      if (timer !== null) stopEvery(timer);
      timer = null;
      if (typeof window !== "undefined") { window.removeEventListener("focus", onBack); document.removeEventListener("visibilitychange", onBack); }
    };
  }

  return { nodes, liveTasks, openDecisions, allTasks, closedTasks, cards, drafts, runs, invalidate, forget, onPoll, tick, subscribers: () => subs.size };
}

export type Reader = ReturnType<typeof createReader>;
/** The app's one reader. */
export const reader = createReader();

// ---- typed metadata ----
/**
 * Fields the app reads that no tag schema declares yet, by kind. Each is written by someone (named), and belongs in uni-tasks' uni_types.py;
 * until then it is listed here, so a field read anywhere else than the schema says is a type error, not a silent `undefined`.
 */
export type Undeclared = {
  task: {
    /** written by the app: snooze, Seen (0.3.6), the revision an answer was given at, a choose ask's pick */
    snoozed_until?: unknown; seen_at?: unknown; seen_by?: unknown; answered_rev?: unknown; decided?: unknown; decided_at?: unknown; decided_by?: unknown;
    /** read by the r18/r19 checks and the look ask's link, but on no live task note (checked 2026-11-10, 0 of 499): candidates to delete */
    link?: unknown; url?: unknown; questions?: unknown; depends_on?: unknown; blocked_by?: unknown; message?: unknown; draft?: unknown;
  };
  decision: { /** on no live decision note (0 of 65): For you's look link */ link?: unknown; url?: unknown };
  card: {};
  run: {
    /** the dispatch ledger's older run shape (steerCore, the work view): on no live run note (0 of 882): candidates to delete */
    what?: unknown; result?: unknown; started?: unknown; updated?: unknown; by?: unknown; message_ref?: unknown; project?: unknown; status?: unknown; merged_into?: unknown; repo?: unknown;
  };
  node: { /** on live node notes, not declared on `node`: a project's repo, a room's other names, a merged project */ repo?: unknown; rooms?: unknown; room_was?: unknown; room_renamed_from?: unknown; merged_into?: unknown };
  draft: { /** on 47 of 250 draft notes, not declared on `draft` */ status?: unknown };
};
/** A kind's metadata as the app reads it: every declared field (and the undeclared ones above), each `unknown` until its parser checks it. */
export type ReadMeta<K extends Kind> = { [F in keyof Meta[K]]?: unknown } & Undeclared[K];
/** Metadata read as several kinds at once (a list that holds tasks and decisions, or the work view's nodes, runs and tasks). */
export type ReadAny<K extends Kind> = UnionToIntersection<K extends Kind ? ReadMeta<K> : never>;
type UnionToIntersection<U> = (U extends unknown ? (x: U) => void : never) extends (x: infer I) => void ? I : never;
/** A note's metadata, typed as `kinds` (an empty object when it has none). */
export const metaOf = <K extends Kind>(n: { metadata?: unknown }, ..._kinds: K[]): ReadAny<K> =>
  (n.metadata && typeof n.metadata === "object" ? n.metadata : {}) as ReadAny<K>;
